const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);let dt=Math.min(clock.getDelta(),.05);elapsed+=dt;if(!paused&&!gameEnded){dt*=speed;if(running){spawnTimer-=dt;if(spawnQueue.length&&spawnTimer<=0){makeEnemy();spawnQueue.shift();spawnTimer=Math.max(.4,.96-wave*.025)}for(const e of [...enemies]){e.progress+=e.speed*dt/route.getLength()*7;if(e.progress>=1){scene.remove(e.group);enemies=enemies.filter(x=>x!==e);lives--;updateHUD();if(lives<=0)endGame();continue}const p=route.getPointAt(e.progress),t=route.getTangentAt(e.progress);e.group.position.set(p.x,0,p.z);e.group.rotation.y=Math.atan2(-t.x,-t.z)}
for(const tower of towers){tower.cd-=dt;if(tower.cd>0)continue;const d=defs[tower.type],range=d.range+(tower.level-1)*.25;let target=null;for(const e of enemies){const dist=Math.hypot(e.group.position.x-tower.x,e.group.position.z-tower.z);if(e.hp>0&&dist<=range&&(!target||e.progress>target.progress))target=e}if(target){const dx=target.group.position.x-tower.x,dz=target.group.position.z-tower.z;tower.group.rotation.y=Math.atan2(-dx,-dz);shoot(tower,target);tower.cd=d.rate/(1+(tower.level-1)*.12)}}
for(const s of [...shots]){s.life-=dt;const frac=1-Math.max(0,s.life)/s.total;if(s.bomb){s.mesh.position.lerpVectors(s.from,s.to,Math.min(1,frac));s.mesh.position.y+=Math.sin(frac*Math.PI)*.65}else if(!s.beam&&s.target?.group){s.mesh.position.lerpVectors(s.from,s.target.group.position.clone().add(new THREE.Vector3(0,.35,0)),Math.min(1,frac))}if(s.life<=0){if(s.bomb){burst(s.to,0xff815b,10);for(const e of [...enemies])if(Math.hypot(e.group.position.x-s.to.x,e.group.position.z-s.to.z)<1.2)damage(e,s.damage)}else if(s.target?.hp>0)damage(s.target,s.damage);scene.remove(s.mesh);shots=shots.filter(x=>x!==s)}}
for(const p of [...particles]){p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);p.vel.y-=2*dt;p.mesh.material.opacity=Math.max(0,p.life*2);if(p.life<=0){scene.remove(p.mesh);particles=particles.filter(x=>x!==p)}}if(running&&!spawnQueue.length&&!enemies.length&&!gameEnded)finishWave();}
